using AcxiomCRM.Data;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCRM.Controllers;[Authorize(Policy="AdminOnly")] public class AuditLogsController:Controller{private readonly ApplicationDbContext _db;public AuditLogsController(ApplicationDbContext db){_db=db;}public async Task<IActionResult> Index(string? q,DateTime? from,DateTime? to,int page=1){var x=_db.AuditLogs.AsQueryable();if(!string.IsNullOrWhiteSpace(q))x=x.Where(a=>a.UserName.Contains(q)||a.Action.Contains(q)||a.EntityName.Contains(q));if(from.HasValue)x=x.Where(a=>a.CreatedDate>=from.Value);if(to.HasValue)x=x.Where(a=>a.CreatedDate<to.Value.AddDays(1));ViewBag.Query=q;ViewBag.From=from?.ToString("yyyy-MM-dd");ViewBag.To=to?.ToString("yyyy-MM-dd");ViewBag.Page=page;ViewBag.Pages=(int)Math.Ceiling(await x.CountAsync()/20.0);return View(await x.OrderByDescending(a=>a.CreatedDate).Skip((Math.Max(1,page)-1)*20).Take(20).ToListAsync());}}
